use std::cell::{RefCell};
use std::rc::{Rc};

fn main() {
    let mut chunks = Rc::new(RefCell::new(Some(Vec::<Rc<RefCell<Option<Vec<String>>>>>::new())));
    let mut patterns = Rc::new(RefCell::new(Some(vec!["a".to_string(), "bb".to_string(), "ccc".to_string()])));
    let mut start = Rc::new(RefCell::new(Some(0)));

    { let new_val = { let __append_target = chunks.clone(); let __append_value = Rc::new(RefCell::new(Some({ let __seq_holder = patterns.clone(); let __seq_guard = __seq_holder.borrow(); let __source_cap = __seq_guard.as_ref().map(|__v| __v.capacity()).unwrap_or(0); let mut __seq = __seq_guard.as_ref().cloned().unwrap_or_default(); drop(__seq_guard); let __low = ((*start.borrow().as_ref().unwrap())) as usize; let __high = (2) as usize; let __max = __source_cap; if __seq.len() < __high { __seq.resize_with(__high, Default::default); }; let _slice = &__seq[__low..__high]; let mut _v = Vec::with_capacity((__max - __low) as usize); _v.extend_from_slice(_slice); _v }))).clone(); (*__append_target.borrow_mut()).get_or_insert_with(Vec::new).push(__append_value); __append_target.clone() }; chunks = new_val; };
    { let new_val = { let __append_target = chunks.clone(); let __append_value = Rc::new(RefCell::new(Some({ let __seq_holder = patterns.clone(); let __seq_guard = __seq_holder.borrow(); let __source_cap = __seq_guard.as_ref().map(|__v| __v.capacity()).unwrap_or(0); let mut __seq = __seq_guard.as_ref().cloned().unwrap_or_default(); drop(__seq_guard); let __low = (2) as usize; let __high = __seq.len(); let __max = __source_cap; if __seq.len() < __high { __seq.resize_with(__high, Default::default); }; let _slice = &__seq[__low..__high]; let mut _v = Vec::with_capacity((__max - __low) as usize); _v.extend_from_slice(_slice); _v }))).clone(); (*__append_target.borrow_mut()).get_or_insert_with(Vec::new).push(__append_value); __append_target.clone() }; chunks = new_val; };

    println!("{} {} {} {} {} {}", format!("{}", (*chunks.borrow()).as_ref().map(|__v| __v.len()).unwrap_or(0)), format!("{}", (*(*chunks.borrow().as_ref().unwrap())[(0) as usize].clone().borrow()).as_ref().map(|__v| __v.len()).unwrap_or(0)), format!("{}", (*(*chunks.borrow().as_ref().unwrap())[(0) as usize].clone().borrow().as_ref().unwrap())[(0) as usize].clone()), format!("{}", (*(*chunks.borrow().as_ref().unwrap())[(0) as usize].clone().borrow().as_ref().unwrap())[(1) as usize].clone()), format!("{}", (*(*chunks.borrow().as_ref().unwrap())[(1) as usize].clone().borrow()).as_ref().map(|__v| __v.len()).unwrap_or(0)), format!("{}", (*(*chunks.borrow().as_ref().unwrap())[(1) as usize].clone().borrow().as_ref().unwrap())[(0) as usize].clone()));
}